# Let's identify distinct clusters by proximity
def make_clusters(points, threshold=8):
    clusters = []
    used = set()
    for p in points:
        if p in used: continue
        cl = [p]
        used.add(p)
        for other in points:
            if other not in used and abs(other[0]-p[0]) < threshold and abs(other[1]-p[1]) < threshold:
                cl.append(other)
                used.add(other)
        if len(cl) > 1:
            clusters.append(sorted(cl))
    return clusters

